Cypher query: MATCH (song:Work), (person:Person), (hamilton:Work)
WHERE (toLower(song.name) CONTAINS 'who lives, who dies, who tells your story' OR any(alias IN coalesce(song.aliases, []) WHERE toLower(alias) CONTAINS 'who lives, who dies, who tells your story'))
  AND (toLower(person.name) CONTAINS 'lin-manuel miranda' OR any(alias IN coalesce(person.aliases, []) WHERE toLower(alias) CONTAINS 'lin-manuel miranda'))
  AND (toLower(hamilton.name) CONTAINS 'hamilton' OR any(alias IN coalesce(hamilton.aliases, []) WHERE toLower(alias) CONTAINS 'hamilton'))
MATCH (song)-[r1]-(person), (song)-[r2]-(hamilton)
RETURN song.name AS song, type(r1) AS connection_to_person, person.name AS person, type(r2) AS relationship_to_hamilton, hamilton.name AS work
LIMIT 10
