[E90a2c4] {"title":"Economy of India","text":"Economy of India
It is upgrading its infrastructure . As of May 2014 , India had completed over 22,600 kilometres ( 14,000 mi ) of 4 - or 6 - lane highways , connecting most of its major manufacturing , commercial and cultural centres . India 's road infrastructure carries 60 % of freight and 87 % of passenger traffic . Indian Railways is the fourth - largest rail network in the world , with a track length of 114,500 kilometres ( 71,100 mi ) and 7,172 stations . This government - owned - and - operated railway network carried an average of 23 million passengers a day , and over a billion tonnes of freight in 2013 . India has a coastline of 7,500 kilometres ( 4,700 mi ) with 13 major ports and 60 operational non-major ports , which together handle 95 % of the country 's external trade by volume and 70 % by value ( most of the remainder handled by air ) . Nhava Sheva , Mumbai is the largest public port , while Mundra is the largest private sea port .","entities":["India","India's road infrastructure","Indian Railways","Nhava Sheva","Mundra","Mumbai","Economy of India"],"facts":["India -PART_OF-> Beekeeping by countries","India -PART_OF-> British Empire","India -PART_OF-> these ten countries","India -PART_OF-> Gondwana","India -PART_OF-> National anthems of Asia"]}

Cypher query: MATCH (n:__Entity__)-[r]-(m:__Entity__)
WHERE (
  toLower(n.name) CONTAINS 'eastern coastal plains'
  OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'eastern coastal plains')
  OR toLower(n.name) CONTAINS 'western coastal plains'
  OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'western coastal plains')
)
RETURN n.name AS plain, type(r) AS relationship, m.name AS related, m.kind AS related_kind,
       coalesce(r.relationship, r.relation, r.role, r.context, r.fact) AS detail
LIMIT 10
